/**
 * Problem bank.
 *
 * `catalog` (catalog.js, generated by scripts/content/build-catalog.mjs) is what the listing views
 * read: titles, difficulties, topics, kinds. Problem modules load only when a problem is opened
 * (`loadProblem`), because each one builds its 10 hidden tests at import time; importing all of
 * them up front blocked the main thread for 12 s (docs/adr/0008-lazy-problem-modules.md).
 * `planned` entries are catalog metadata only, so the dashboard can show the curriculum shape.
 * To add a problem: see docs/PROBLEM_FORMAT.md or run the /add-problem Claude Code command.
 */
import entries from './catalog.js';

export const TOPICS = [
  { id: 'arrays-strings', label: 'Arrays / Strings' },
  { id: 'greedy', label: 'Greedy' },
  { id: 'dp', label: 'Dynamic Programming' },
  { id: 'graphs', label: 'Graphs' },
  { id: 'trees', label: 'Trees' },
  { id: 'sql', label: 'SQL' },
];

/** @type {import('./hydrate.js').CatalogEntry[]} Full catalog for listing UIs, available first, then planned. */
export const catalog = entries;

export const DIFFICULTIES = ['Easy', 'Medium', 'Hard'];

const byId = new Map(catalog.map((e) => [e.id, e]));
/** @type {Map<string, Promise<object>>} */
const loaded = new Map();

/**
 * The catalog entry of a published problem, without loading its module.
 * @param {string} id
 * @returns {import('./hydrate.js').CatalogEntry|null} null for unknown and planned ids
 */
export function catalogEntry(id) {
  const e = byId.get(id);
  return e && e.status === 'available' ? e : null;
}

/** @returns {import('./hydrate.js').CatalogEntry[]} the published problems, in catalog order */
export function availableEntries() {
  return catalog.filter((e) => e.status === 'available');
}

/**
 * Loads and hydrates one problem module. Memoised: a problem is imported and its tests built once
 * per page. Rejects for ids that are not published (never imports a path built from an unknown id)
 * and when the import fails; a failed import is forgotten so the next call retries.
 * @param {string} id
 * @returns {Promise<object>} the hydrated problem
 */
export function loadProblem(id) {
  // don't touch / the id becomes part of an import path: only catalog ids may get that far
  if (!catalogEntry(id)) return Promise.reject(new Error(`Unknown problem "${id}"`));
  let p = loaded.get(id);
  if (!p) {
    // Hydration needs codegen, adapters and the SQL engine; loading them here keeps them out of
    // the listing views' module graph.
    p = Promise.all([import(`./${id}/problem.js`), import('./hydrate.js')]).then(([mod, { hydrate }]) => hydrate(mod.default));
    loaded.set(id, p);
    p.catch(() => loaded.delete(id));
  }
  return p;
}

/**
 * Every published problem, hydrated, in catalog order. For tests, the verifier and scripts; a page
 * should never need all of them.
 * @returns {Promise<object[]>}
 */
export function loadAllProblems() {
  return Promise.all(availableEntries().map((e) => loadProblem(e.id)));
}

/**
 * Fetches the reference solution for "Reveal Solution". Solutions are separate files (not
 * bundled into the module) so every language is a real, compilable file the verifier checks.
 * @param {string} problemId
 * @param {string} lang
 * @returns {Promise<string>}
 */
export async function loadSolution(problemId, lang) {
  const { solutionUrl } = await import('./hydrate.js');
  const res = await fetch(solutionUrl(problemId, lang));
  if (!res.ok) throw new Error(`No ${lang} solution for ${problemId} (${res.status})`);
  return res.text();
}
